ng><small>${STATE.rank} · Level ${STATE.level}</small></div></div><div class="notice" style="margin-top:18px">Your local leaderboard scores update as you discover elements, win battles, and craft recipes. Online accounts and shared leaderboards need a game server, so this profile stays on this device.</div></section></div>`}\nfunction createAccount(){const name=$('#accountName').value.trim(),avatar=$('#accountAvatar').value;if(!/^[\\p{L}\\p{N} _'-]{2,20}$/u.test(name)){toast('Use 2–20 letters, numbers, spaces, or _ - \' characters.');return}STATE.profileName=name;STATE.profileAvatar=avatar;STATE.profileCreated=true;save();render();toast('Explorer profile saved!')}
