 function studioPage(){const code=`CANOPY-${STATE.levelNo.toString(36).toUpperCase()}${(STATE.xp%1296).toString(36).toUpperCase().padStart(2,'0')}`;return `<div class="page-title"><div><h1>Creator's clearing</h1><p>Make elements, design a level, or invite a friend into your rules.</p></div><span class="pill">✎ Studio</span></div><div class="two-col"><section class="content-card"><h2 style="font:22px Georgia,serif">Custom element maker</h2><p style="font-size:11px;color:var(--muted)">Add a personal T1 element to your world.</p><div class="form-row"><input id="customName" class="input" placeholder="Element name (e.g. Bloom)" maxlength="20"><input id="customIcon" class="input" placeholder="Icon 🌸" maxlength="4" style="max-width:90px"></div><div class="form-row"><select class="select" id="customStrength"><option>Water</option><option>Fire</option><option>Earth</option><option>Air</option></select><select class="select" id="customWeak"><option>Fire</option><option>Water</option><option>Air</option><option>Earth</option></select></div><button class="button" onclick="createElement()">Create element</button><div class="notice">Custom creations join your collection and can be merged with other T1 elements.</div><div class="recipe-list">${STATE.custom.map(x=>`<div class="recipe-item"><span>${x.icon}</span><div><strong>${safe(x.name)} <small>· Custom T1</small></strong><small>Strong vs ${x.strength} · Weak vs ${x.weak}</small></div></div>`).join('')}</div></section><section class="content-card"><h2 style="font:22px Georgia,serif">Level maker</h2><p style="font-size:11px;color:var(--muted)">Design a little trail, then play it immediately.</p><div class="form-row"><input id="levelName" class="input" placeholder="Your level name"><select id="levelTheme" class="select"><option>🌿 Mosslight Grove</option><option>🌙 Moonwell Clearing</option><option>🔥 Emberglow Hollow</option><option>🌊 Whispering Brook</option></select></div><div class="form-row"><select class="select" id="levelRarity"><option>Calm · Common finds</option><option>Curious · More mixed</option><option>Wild · Rare finds</option></select><input id="levelReward" class="input" type="number" min="10" max="100" value="30" placeholder="Reward"></div><button class="button" onclick="createLevel()">Save & play level</button><div class="section-head"><div><h2 style="font-size:18px">Community trails</h2><p>Custom levels live on this device.</p></div></div><div class="level-list">${STATE.customLevels.map((l,i)=>`<div class="level-item"><span class="emoji">${l.icon}</span><div><strong>${safe(l.name)}</strong><small>${safe(l.rarity)} · rank ${l.rank} · played ${l.plays}x</small></div><button class="mini-button" onclick="playLevel(${i})">Play</button></div>`).join('')||'<div class="notice">No custom trails yet. Make the first!</div>'}</div></section></div><div class="section-head"><div><h2>Gamemode workshop</h2><p>Set your own rules and share a room code with a friend.</p></div></div><section class="content-card"><div class="two-col"><div><h2 style="font:20px Georgia,serif">Custom rules</h2><div class="form-row"><input id="modeName" class="input" placeholder="Gamemode name"><select class="select" id="modeRule"><option>Double damage</option><option>One-heart challenge</option><option>Lucky forest</option><option>Free merge</option></select></div><button class="button" onclick="createMode()">Create gamemode</button><div class="recipe-list" style="margin-top:10px">${STATE.customModes.map(m=>`<div class="recipe-item"><span>🎮</span><div><strong>${safe(m.name)}</strong><small>${safe(m.rule)}</small></div><button class="mini-button" onclick="toast('Mode active: ${safe(m.name)}')">Play</button></div>`).join('')}</div></div><div><h2 style="font:20px Georgia,serif">Friend room</h2><p style="font-size:11px;color:var(--muted)">Share this code to invite a friend. Enter a friend's code to join their local challenge.</p><div class="notice" style="font-size:16px;text-align:center;letter-spacing:.14em;color:var(--lime)">${code}</div><div class="form-row"><button class="button secondary" onclick="copyCode('${code}')">Copy invite code</button></div><div class="form-row"><input id="joinCode" class="input" placeholder="Friend's room code"><button class="mini-button" onclick="joinRoom()">Join</button></div><small style="color:#8da495;font-size:9px">Room codes set up a friendly local challenge. Live online multiplayer is not connected in this offline build.</small></div></div></section>`}
