 function showBoard(t){$('#boardRows').innerHTML=boardRows(t)}\nfunction accountPage(){const name=STATE.profileName||'Fern Walker',avatar=STATE.profileAvatar||'🧙';return `<div class="page-title"><div><h1>Explorer account</h1><p>Create a local profile for your Canopy adventures.</p></div><span class="pill">${STATE.profileCreated?'✦ Profile ready':'🌱 New profile'}</span></div><div class="two-col"><section class="content-card"><h2 style="font:23px Georgia,serif">${STATE.profileCreated?'Your explorer profile':'Make your account'}</h2><p style="color:var(--muted);font-size:12px;line-height:1.6">Choose the name and avatar shown on your profile and leaderboard. Your progress is saved in this browser.</p><div style="display:grid;gap:8px;margin:20px 0"><label for="accountName" style="font-size:11px;color:var(--muted)">Explorer name</label><input id="accountName" maxlength="20" value="${safe(name)}" placeholder="e.g. MossyMoth" style="width:100%;background:#11201a;border:1px solid #ffffff1b;border-radius:9px;color:var(--cream);padding:11px;outline:none"><label for="accountAvatar" style="font-size:11px;color:var(--muted);margin-top:8px">Choose an avatar</label><select id="accountAvatar" class="select"><option ${avatar==='🧙'?'selected':''}>🧙</option><option ${avatar==='🌿'?'selected':''}>🌿</option><option ${avatar==='🦊'?'selected':''}>🦊</option><option ${avatar==='🦉'?'selected':''}>🦉</option><option ${avatar==='🐸'?'selected':''}>🐸</option><option ${avatar==='🍄'?'selected':''}>🍄</option><option ${avatar==='🦋'?'selected':''}>🦋</option></select></div><button class="button" onclick="createAccount()">${STATE.profileCreated?'Save profile':'Create profile'}</button> <button class="button secondary" onclick="navTo('rank')">View leaderboard →</button></section><section class="content-card"><h2 style="font:23px Georgia,serif">Profile preview</h2><div class="level-item" style="margin-top:18px"><span class="emoji" style="font-size:30px">${safe(avatar)}</span><div><strong>${safe(name)}</strong><small>${STATE.rank} · Level ${STATE.level}</small></div></div><div class="notice" style="margin-top:18px">Your local leaderboard scores update as you discover elements, win battles, and craft recipes. Online accounts and shared leaderboards need a game server, so this profile stays on this device.</div></section></div>`}\nfunction createAccount(){const name=$('#accountName').value.trim(),avatar=$('#accountAvatar').value;if(!/^[\\p{L}\\p{N} _'-]{2,20}$/u.test(name)){toast('Use 2–20 letters, numbers, spaces, or _ - \' characters.');return}STATE.profileName=name;STATE.profileAvatar=avatar;STATE.profileCreated=true;save();render();toast('Explorer profile saved!')}
