function accountPage(){
const name=STATE.profileName||'Fern Walker';
const avatar=STATE.profileAvatar||'🧙';
const status=STATE.profileCreated?'✦ Profile ready':'🌱 New profile';
const heading=STATE.profileCreated?'Your explorer profile':'Make your account';
const action=STATE.profileCreated?'Save profile':'Create profile';
const avatars=['🧙','🌿','🦊','🦉','🐸','🍄','🦋'];
const options=avatars.map(a=>`<option ${a===avatar?'selected':''}>${a}</option>`).join('');
return `<div class="page-title"><div><h1>Explorer account</h1><p>Create a local profile for your Canopy adventures.</p></div><span class="pill">${status}</span></div><div class="two-col"><section class="content-card"><h2 style="font:23px Georgia,serif">${heading}</h2><p style="color:var(--muted);font-size:12px;line-height:1.6">Choose the name and avatar shown on your profile and leaderboard. Your progress is saved in this browser.</p><div style="display:grid;gap:8px;margin:20px 0"><label for="accountName" style="font-size:11px;color:var(--muted)">Explorer name</label><input id="accountName" maxlength="20" value="${safe(name)}" placeholder="e.g. MossyMoth" style="width:100%;background:#11201a;border:1px solid #ffffff1b;border-radius:9px;color:var(--cream);padding:11px;outline:none"><label for="accountAvatar" style="font-size:11px;color:var(--muted);margin-top:8px">Choose an avatar</label><select id="accountAvatar" class="select">${options}</select></div><button class="button" onclick="createAccount()">${action}</button> <button class="button secondary" onclick="navTo('rank')">View leaderboard →</button></section><section class="content-card"><h2 style="font:23px Georgia,serif">Profile preview</h2><div class="level-item" style="margin-top:18px"><span class="emoji" style="font-size:30px">${safe(avatar)}</span><div><strong>${safe(name)}</strong><small>${STATE.rank} · Level ${STATE.level}</small></div></div><div class="notice" style="margin-top:18px">Your local leaderboard scores update as you discover elements, win battles, and craft recipes. Online accounts and shared leaderboards need a game server, so this profile stays on this device.</div></section></div>`;
}
function createAccount(){
const name=$('#accountName').value.trim();
const avatar=$('#accountAvatar').value;
if(name.length<2||name.length>20||!/^[A-Za-z0-9 _-]+$/.test(name)){toast('Use 2–20 letters, numbers, spaces, underscores, or hyphens.');return}
STATE.profileName=name;
STATE.profileAvatar=avatar;
STATE.profileCreated=true;
save();
render();
toast('Explorer profile saved!');
}

